
import React, { useEffect, useRef } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls";

export default function DNABackground() {
  const mountRef = useRef(null);

  useEffect(() => {
    const mount = mountRef.current;

    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, mount.clientWidth / mount.clientHeight, 0.1, 1000);
    camera.position.z = 20;

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(mount.clientWidth, mount.clientHeight);
  renderer.setClearColor(0xffffff, 1);
    mount.appendChild(renderer.domElement);

    // DNA Helix
    const helixGroup = new THREE.Group();
    const helixMaterial1 = new THREE.MeshPhongMaterial({ color: 0x00ffff });
    const helixMaterial2 = new THREE.MeshPhongMaterial({ color: 0xff00ff });
    const sphereGeometry = new THREE.SphereGeometry(0.2, 16, 16);

    const turns = 40;
    const step = 0.3;
    for (let i = 0; i < turns; i++) {
      const angle = i * 0.3;
      const x1 = Math.cos(angle) * 2;
      const y = (i - turns / 2) * step;
      const z1 = Math.sin(angle) * 2;

      const x2 = Math.cos(angle + Math.PI) * 2;
      const z2 = Math.sin(angle + Math.PI) * 2;

      const sphere1 = new THREE.Mesh(sphereGeometry, helixMaterial1);
      sphere1.position.set(x1, y, z1);
      helixGroup.add(sphere1);

      const sphere2 = new THREE.Mesh(sphereGeometry, helixMaterial2);
      sphere2.position.set(x2, y, z2);
      helixGroup.add(sphere2);
    }

    scene.add(helixGroup);

    // Lighting
    const light = new THREE.PointLight(0xffffff, 1);
    light.position.set(10, 10, 10);
    scene.add(light);
    scene.add(new THREE.AmbientLight(0x404040));

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableZoom = false;

    // Animation loop
    const animate = () => {
      requestAnimationFrame(animate);
      helixGroup.rotation.y += 0.01;
      renderer.render(scene, camera);
    };

    animate();

    return () => {
      mount.removeChild(renderer.domElement);
    };
  }, []);

    return (
      <div
        ref={mountRef}
        className="fixed top-0 left-0 w-full h-full"
        style={{ pointerEvents: 'none', minHeight: '100vh', minWidth: '100vw', zIndex: -10 }}
      />
    );
}
